    @Test void savedFontSlotControlsSurviveNeighborEditsAndDetectReintroducedSourceSlots()throws Exception{
        Case c=source(slotRun("Latin words"));DocxEditResult first=applySlots(c,List.of());String ledger=JsonUtils.write(List.of(DraftNativeLayout.info("SCC","libreoffice",first)));TemplateIndex current=first.getIndex();Paragraph before=current.mainParagraph(1);DocxEditResult shifted=EDITOR.apply(first.getDocxBytes(),new SourceEditBatch(current.getSourceSha256(),List.of(Edit.insertParagraphs("neighbor",before,true,List.of("New paragraph"),before))));assertEquals("applied",layout(DraftNativeLayout.bodyLedger(ledger,shifted)).get("status"));
        Map<String,byte[]> parts=unzip(first.getDocxBytes());String xml=new String(parts.get(MAIN),StandardCharsets.UTF_8);assertTrue(xml.contains("<w:rFonts "));parts.put(MAIN,xml.replaceFirst("<w:rFonts ","<w:rFonts w:eastAsia=\"Reintroduced font\" ").getBytes(StandardCharsets.UTF_8));byte[] altered=zip(parts);TemplateIndex reread=EDITOR.inspect(altered);DocxEditResult result=EDITOR.apply(altered,new SourceEditBatch(reread.getSourceSha256(),List.of()));Map<String,Object> invalid=layout(DraftNativeLayout.bodyLedger(ledger,result));assertEquals("unavailable",invalid.get("status"));assertEquals("CHANGED_LAYOUT_CONTROL",DraftBusinessRules.asMap(DraftBusinessRules.list(invalid.get("actions")).get(0)).get("status"));
    }
    @Test void actualRegisteredSccTwoFontSlotParagraphsReverseSevenAttributesAndKeepCompleteSource()throws Exception{
        String dir=System.getProperty("consense.acceptance.sourceDir");assumeTrue(dir!=null,"Explicit original 2a directory required");byte[] bytes=Files.readAllBytes(Paths.get(dir,"06_Special Conditions of Contract (SCC).docx"));TemplateIndex index=EDITOR.inspect(bytes);assertEquals("9aa2fa06683652548e72dbf955c3f236d86cb0958a8fdf3b1ff6cf75b65c7208",index.getSourceSha256());
        Map<String,Object> registry=JsonUtils.mapper().readValue(getClass().getResourceAsStream("/drafting/libreoffice-native-layout.json"),Map.class);Map<String,Object> registered=DraftBusinessRules.list(registry.get("sources")).stream().map(DraftBusinessRules::asMap).filter(row->index.getSourceSha256().equals(row.get("sourceSha256"))).findFirst().orElseThrow(AssertionError::new);List<Object> targets=DraftBusinessRules.list(registered.get("latinFontSlotParagraphs"));assertEquals(2,targets.size());List<NodeAnchor> anchors=new ArrayList<>();Set<String> actualIds=new HashSet<>();for(Object raw:targets){Map<String,Object> row=DraftBusinessRules.asMap(raw);NodeAnchor anchor=index.anchor(String.valueOf(row.get("paragraphId")));assertEquals(row.get("paragraphSha256"),anchor.getSha256());assertTrue(actualIds.add(anchor.getId()));anchors.add(anchor);}assertEquals(Set.of("word/document.xml#/w:document[1]/w:body[1]/w:p[977]","word/document.xml#/w:document[1]/w:body[1]/w:p[1807]"),actualIds);assertNotNull(DraftNativeLayout.plan(index,"SCC","libreoffice"));
        DocxEditResult result=EDITOR.applyWithParagraphBookmarks(bytes,new SourceEditBatch(index.getSourceSha256(),List.of()),Map.of(),false,slots(new NativeLayoutPlan(index.getSourceSha256(),"actual-source-font-slots-isolated",List.of(),List.of()),anchors));List<NativeLayoutChange> changes=slotChanges(result);assertEquals(2,changes.size());Document original=parse(unzip(bytes).get(MAIN)),saved=parse(unzip(result.getDocxBytes()).get(MAIN));List<Element> before=elements(original,W,"p"),after=elements(saved,W,"p");assertEquals(before.size(),after.size());int restored=0;for(NativeLayoutChange change:changes){assertEquals("APPLIED",change.getStatus());Paragraph source=index.paragraph(change.getSource().getId());assertEquals(source.getText(),result.getIndex().paragraph(change.getGeneratedId()).getText());assertTrue(normalizedSlots(result.getIndex().paragraph(change.getGeneratedId())));restored+=undoSlots(before.get(source.getOrdinal()-1),after.get(source.getOrdinal()-1),change.getLayoutId());}assertEquals(7,restored);assertEquals(shape(original.getDocumentElement()),shape(saved.getDocumentElement()));unchanged(unzip(bytes),unzip(result.getDocxBytes()),Set.of(MAIN));
    }
    private static Map<String,Object> layout(List<Object> rows){for(Object raw:rows){Map<String,Object> row=DraftBusinessRules.asMap(raw);if("native_layout".equals(row.get("kind")))return row;}throw new AssertionError("Native layout ledger missing");}
